"""The running commit comes from the jar, not from a pod label."""
from roottrace.buildinfo import pick_git_entry, repo_for, revision_from

AUTH_GIT = """\
#Generated by Git-Commit-Id-Plugin
#Tue Sep 22 13:51:39 UTC 2026
git.build.time=2026-09-22T13\\:51\\:39+0000
git.build.version=1.3.1
git.commit.id.abbrev=fa3d713
git.commit.id.full=fa3d713f2de9fcb00b8e87abba38a8c2e06557fa
"""
AUTH_BUILD = """\
build.artifact=authentication-service
build.group=io.mosip.authentication
build.name=authentication-service
build.time=2026-09-22T13\\:50\\:34.405Z
build.version=1.3.1
"""
KM_GIT = """\
git.commit.id.abbrev=4af5e8b
git.commit.id.full=4af5e8bf167c6dcfea37f9b22d2f3750b2f3f8df
git.build.version=1.4.1-SNAPSHOT
"""
KM_BUILD = """\
build.artifact=kernel-keymanager-service
build.group=io.mosip.kernel
build.version=1.4.1-SNAPSHOT
"""


def main():
    assert pick_git_entry([
        "BOOT-INF/classes/service-git.properties", "META-INF/build-info.properties",
    ]) == "BOOT-INF/classes/service-git.properties"
    assert pick_git_entry(["BOOT-INF/classes/git.properties"]) == "BOOT-INF/classes/git.properties"
    assert pick_git_entry(["META-INF/MANIFEST.MF"]) is None

    auth = revision_from(AUTH_GIT, AUTH_BUILD)
    assert auth.commit == "fa3d713f2de9fcb00b8e87abba38a8c2e06557fa"
    assert auth.commit_abbrev == "fa3d713"
    assert auth.version == "1.3.1"
    assert auth.group == "io.mosip.authentication"
    assert auth.artifact == "authentication-service"
    assert "\\:" not in (auth.version or "")

    km = revision_from(KM_GIT, KM_BUILD)
    assert km.commit.startswith("4af5e8b")
    assert km.group == "io.mosip.kernel"
    assert km.artifact == "kernel-keymanager-service"
    assert km.version == "1.4.1-SNAPSHOT"

    # esignet writes git.properties as JSON, not Java properties.
    esignet = revision_from(
        '{ "git.commit.id.full" : "4a1055b70c9c1c0ec764b92c9a02d38778d5f509",'
        ' "git.commit.id.abbrev" : "4a1055b", "git.build.version" : "1.4.1" }',
        "build.group=io.mosip.esignet\nbuild.artifact=esignet-service\nbuild.version=1.4.1\n",
    )
    assert esignet.commit == "4a1055b70c9c1c0ec764b92c9a02d38778d5f509"
    assert esignet.group == "io.mosip.esignet"
    assert esignet.version == "1.4.1"

    from importlib import resources
    import yaml
    sources = yaml.safe_load(resources.files("roottrace").joinpath("sources.yaml").read_text())["sources"]
    hit = repo_for("io.mosip.kernel.keymanager.hsm.impl.pkcs.PKCS11KeyStoreImpl", sources)
    assert hit["repo"].endswith("/keymanager"), hit
    assert repo_for("io.mosip.kernel.keymanagerservice.KeymanagerService", sources)["repo"].endswith("/keymanager")
    auth = repo_for("io.mosip.authentication.core.spi.indauth.service.DemoService", sources)
    assert auth["repo"].endswith("/id-authentication")
    assert repo_for("io.mosip.kernel.auth.service.TokenService", sources)["repo"].endswith("/mosip-openid-bridge")
    assert repo_for("io.mosip.registration.processor.packet.PacketReceiver", sources)["repo"].endswith("/registration")
    assert repo_for("io.mosip.kernel.authmanager.service.TokenService", sources) is None
    assert repo_for("io.mosip.kernel.core.util.DateUtils2", sources)["repo"].endswith("/commons")
    assert repo_for("io.mosip.kernel.dataaccess.hibernate.repository.impl.HibernateRepositoryImpl", sources)["repo"].endswith("/commons")
    assert repo_for("io.mosip.commons.packet.keeper.PacketKeeper", sources)["repo"].endswith("/packet-manager")
    assert repo_for("io.mosip.commons.packetmanager.PacketManagerService", sources)["repo"].endswith("/packet-manager")

    print("BUILD INFO CHECKS PASSED")


if __name__ == "__main__":
    main()
